using System; using UnityEditor; using UnityEditor.SceneManagement; using UnityEngine; public static class Phase4A_TopLevelIntegrationFix { public static void Run(){try{var sc=EditorSceneManager.OpenScene("Assets/Scenes/147VR_MainScene.unity"); var table=GameObject.Find("Prefab_WPBSA_12Foot_Snooker"); if(table==null)throw new Exception("table missing"); var wrap=GameObject.Find("147VR_TABLE_INTEGRATION_UNIT_ROOT"); if(wrap==null){wrap=new GameObject("147VR_TABLE_INTEGRATION_UNIT_ROOT");} var wt=wrap.transform; wt.SetParent(null,false); wt.position=Vector3.zero; wt.rotation=Quaternion.identity; wt.localScale=Vector3.one; table.transform.SetParent(wt,false); table.transform.localPosition=Vector3.zero; table.transform.localRotation=Quaternion.identity; table.transform.localScale=Vector3.one; var visual=Find(table.transform,"Visual_Meshes_Drop_Here"); var surface=Find(table.transform,"TABLE SURFACE"); if(visual==null||surface==null)throw new Exception("visual/surface missing"); visual.localRotation=Quaternion.Euler(0,90,0); surface.localRotation=Quaternion.identity; PrefabUtility.RecordPrefabInstancePropertyModifications(table.transform); PrefabUtility.RecordPrefabInstancePropertyModifications(visual); PrefabUtility.RecordPrefabInstancePropertyModifications(surface); EditorUtility.SetDirty(wrap); EditorSceneManager.MarkSceneDirty(sc); EditorSceneManager.SaveScene(sc); Debug.Log($"[4A TOPLEVEL FIX] wrap={wt.lossyScale} table={table.transform.lossyScale} visual={visual.eulerAngles} surfaceLocal={surface.localEulerAngles}"); EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(3);}} static Transform Find(Transform r,string n){foreach(var t in r.GetComponentsInChildren<Transform>(true))if(t.name==n)return t;return null;} }

